const total=items.length;
let found=new Set(), hintsLeft=3, seconds=0, timerId=null, zoom=1, toastId;
const $=s=>document.querySelector(s);
const scene=$('#scene'), objects=$('#objects'), list=$('#targetList');
$('#count').textContent=`0 / ${total}`;$('#remaining').textContent=`${total} hidden`;
// Spread the clues across the whole room, then shuffle their locations so the clue order gives nothing away.
const positions=[];
for(let row=0;row<6;row++)for(let col=0;col<11;col++)positions.push({x:5+col*9+((row*7+col*3)%5-2)*.75,y:17+row*12.1+((col*5+row*2)%5-2)*.75});
let seed=8931;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
for(let i=positions.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[positions[i],positions[j]]=[positions[j],positions[i]]}
items.forEach((item,i)=>{
 const [emoji,name]=item,p=positions[i];
 const obj=document.createElement('button');obj.className='object';obj.type='button';obj.textContent=emoji;obj.style.left=`${p.x}%`;obj.style.top=`${p.y}%`;obj.setAttribute('aria-label',name);obj.title=name;obj.dataset.id=i;
 obj.addEventListener('click',()=>find(i));objects.appendChild(obj);
 const clue=document.createElement('button');clue.className='target';clue.type='button';clue.dataset.id=i;clue.innerHTML=`<span class="emoji">${emoji}</span><span class="name">${name}</span>`;clue.setAttribute('aria-label',`Show ${name} in the room`);clue.addEventListener('click',()=>spot(i));list.appendChild(clue);
});
function formatTime(n){return`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function startClock(){if(timerId===null)timerId=setInterval(()=>{$('#timer').textContent=formatTime(++seconds)},1000)}
function find(id){if(found.has(id))return;startClock();found.add(id);document.querySelector(`.object[data-id="${id}"]`).classList.add('found');document.querySelector(`.target[data-id="${id}"]`).classList.add('done');const n=found.size;$('#count').textContent=`${n} / ${total}`;$('#remaining').textContent=`${total-n} hidden`;$('#progress').style.width=`${n/total*100}%`;if(n===total){clearInterval(timerId);timerId=null;$('#finalTime').textContent=`Finished in ${formatTime(seconds)}.`;$('#winModal').classList.add('open')}else if(n===total-1){notify('So close — one last object!')}else if(n%10===0){notify(`Lovely spotting! ${n} found so far.`)}}
function spot(id){const obj=document.querySelector(`.object[data-id="${id}"]`);if(found.has(id)){notify('You already found that one!');return}obj.scrollIntoView({behavior:'smooth',block:'center',inline:'center'});obj.classList.remove('hinting');void obj.offsetWidth;obj.classList.add('hinting');setTimeout(()=>obj.classList.remove('hinting'),2200)}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastId);toastId=setTimeout(()=>t.classList.remove('show'),2100)}
function giveHint(){if(found.size===total)return;if(!hintsLeft){notify('No hints left — use the clue list to search for an item!');return}const remaining=items.map((_,i)=>i).filter(i=>!found.has(i));const id=remaining[Math.floor(Math.random()*remaining.length)];hintsLeft--;$('#hints').textContent=`${hintsLeft} left`;notify(`Look for ${items[id][0]} ${items[id][1]}!`);spot(id)}
function restart(){found.clear();seconds=0;hintsLeft=3;clearInterval(timerId);timerId=null;$('#timer').textContent='00:00';$('#hints').textContent='3 left';$('#count').textContent=`0 / ${total}`;$('#remaining').textContent=`${total} hidden`;$('#progress').style.width='0%';document.querySelectorAll('.object,.target').forEach(el=>el.classList.remove('found','done','hinting'));$('#winModal').classList.remove('open');notify('Fresh start — happy hunting!')}
$('#hintTop').addEventListener('click',giveHint);$('#restartTop').addEventListener('click',restart);$('#playAgain').addEventListener('click',restart);
$('#filter').addEventListener('input',e=>{const q=e.target.value.trim().toLocaleLowerCase();document.querySelectorAll('.target').forEach(el=>{el.classList.toggle('hidden',!el.querySelector('.name').textContent.toLocaleLowerCase().includes(q))})});
$('#zoomIn').addEventListener('click',()=>{zoom=Math.min(1.35,zoom+.1);scene.style.width=`${zoom*100}%`;scene.style.minWidth=`${820*zoom}px`});$('#zoomOut').addEventListener('click',()=>{zoom=Math.max(1,zoom-.1);scene.style.width=`${zoom*100}%`;scene.style.minWidth=`${820*zoom}px`});
</script>
</body>
</html>

